        # Higher-order polynomial with more chaotic coefficients
        sum_x = np.sum(x)
        result += 0.3 * (sum_x**9 - 4*sum_x**7 + 3*sum_x**5 - sum_x**3)

        # Enhanced multi-scale oscillatory component
